head.script:
///////// 1. 변수 및 선언 영역 /////////
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.BYCORP_CHRG_BZ_TP_CD = "", scwin.INVSTCOM_BZ_TP_CD = "", scwin.newYN = "";
scwin.trsIdx; // insert, update 구분

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.BYCORP_CHRG_BZ_TP_CD = (arrPar.length >= 5 ? arrPar[4] : ""); // elw/etn/etf 구분
            scwin.INVSTCOM_BZ_TP_CD = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/LP 구분값
            scwin.newYN = (arrPar.length >= 7 ? arrPar[6] : ""); //  신규여부

        }

        // fn_checkGubun() ;
        txb_ISUR_NM.setValue(scwin.Isur_nm);
        if (scwin.INVSTCOM_BZ_TP_CD === "1") txb_INVSTCOM_BZ_TP_CD.setValue("발행사");

        else if (scwin.INVSTCOM_BZ_TP_CD === "2") txb_INVSTCOM_BZ_TP_CD.setValue("유동성공급사");

        else if (scwin.INVSTCOM_BZ_TP_CD === "3") txb_INVSTCOM_BZ_TP_CD.setValue("운용사");
        if (scwin.BYCORP_CHRG_BZ_TP_CD === "3") txb_BYCORP_CHRG_BZ_TP_CD.setValue("ELW");

        else if (scwin.BYCORP_CHRG_BZ_TP_CD === "6") txb_BYCORP_CHRG_BZ_TP_CD.setValue("ETN");

        else if (scwin.BYCORP_CHRG_BZ_TP_CD === "5") txb_BYCORP_CHRG_BZ_TP_CD.setValue("ETF");

        else if (scwin.BYCORP_CHRG_BZ_TP_CD === "7") txb_BYCORP_CHRG_BZ_TP_CD.setValue("상장형 수익증권");

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        if (scwin.newYN === "Y") {
            await scwin.newOnload(); // 신규작성시 호출

        } else {
            await scwin.search();
        }
        $c.cm.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41111.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// function fn_drft() { }
// function fn_makt() { }

/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41111.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');

        // if (buttonSet.status == "D") { // 삭제처리의 응답인 경우
        //    frame.CloseFrame();
        // }
        // else {
        //    fn_search();
        // }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41111.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.newYN === "Y") {
            buttonSet.setInsertStatus();
        } else {
            buttonSet.setUpdateStatus();
            //    setButtonSetWithDate( edt_MktactEnforceDd , false ) ;

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41111.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41111.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // if (fr_bz_procs_no != "")
    // {
    url += "?SCREN_ID=" + "ULDSTF41111.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=ELW_ETF_COM_CONTACT_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwetf.comcontact.select.isurcd.Search" + "&{P}param01=" + scwin.BYCORP_CHRG_BZ_TP_CD + "&{P}param02=" + scwin.INVSTCOM_BZ_TP_CD + // 법인코드
        "&{P}param03=" + scwin.Isur_cd; // 시작일자

    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // }

};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    url += "?SCREN_ID=" + "ULDSTF41111.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=ELW_ETF_COM_CONTACT_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwetf.comcontact.select.isurcd.new.dummy" + "&{P}param01=" + scwin.BYCORP_CHRG_BZ_TP_CD + "&{P}param02=" + scwin.INVSTCOM_BZ_TP_CD + // 법인코드
        "&{P}param03=" + scwin.Isur_cd; // 시작일자

    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description save Trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/ELWUnderlyingAsset.do",
        ref : "dts_Mst",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkGubun
 * @description check Gubun 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkGubun = function() {
    if (gubun === '1') {
        txb_AfchgElwIsurNm.setReadOnly(false);
        txb_AfchgElwIsurEngNm.setReadOnly(false);
        txb_AfchgUlyNm.setReadOnly(true);
        txb_AfchgUlyEngNm.setReadOnly(true);
    } else if (gubun === '2') {
        txb_AfchgElwIsurNm.setReadOnly(true);
        txb_AfchgElwIsurEngNm.setReadOnly(true);
        txb_AfchgUlyNm.setReadOnly(false);
        txb_AfchgUlyEngNm.setReadOnly(false);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (!$c.stf.checkEmptyValue(txb_AFCHG_CHRG_NM, "변경후 담당자")) return false;
    if (!$c.stf.checkEmptyValue(txb_AFCHG_TEL_NO, "변경후 전화번호")) return false;
    if (!$c.stf.checkEmptyValue(txb_AFCHG_EMAIL, "변경 후 이메일")) return false;
    if (!$c.lce.fn_checkPhoneNumber(txb_AFCHG_TEL_NO.getValue())) {
        await $c.win.alert("[전화번호 형식이 일치하지 않습니다.]");
        txb_AFCHG_TEL_NO.focus();
        return false;
    }
    if (!$c.stf.IsValidEmail(txb_AFCHG_EMAIL.getValue())) {
        await $c.win.alert("[이메일 형식이 일치하지 않습니다.]");
        txb_AFCHG_EMAIL.focus();
        return false;
    }
    return true;
};

