/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        // fr_bz_procs_no = fn_getNewBzProcNo( dts_BzProcsNo );

        // if (fr_bz_procs_no.length != 14) {
        //    alert(getMessageParam("MSG-0010", ""));
        // } else {

        scwin.trsIdx = TRS_IDX_INSERT;

        // dts_Mst.NameString(dts_Mst.RowPosition, "BZ_PROCS_NO") = fr_bz_procs_no;
        // dts_Mst.NameString(dts_Mst.RowPosition, "ISUR_CD") = Isur_cd;

        // fn_SetValue() ;
        await scwin.saveTrs();
        // }

    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};
